const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-123.6, 46.3]); // Dallasport, WA approximate coordinates
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';

  // 2. Data Acquisition - ERA5-Land for temperature
  const tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(point)
    .select('temperature_2m');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`July 2022 temperature images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate maximum temperature for the month
  const maxTempImage = tempCollection.max();

  // 4. Calculation - Get temperature value and convert from Kelvin to Fahrenheit
  const tempResult = maxTempImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  }).get('temperature_2m');

  const tempKelvin = tempResult.getInfo();

  // Check for invalid temperature
  if (tempKelvin === null || tempKelvin === undefined || tempKelvin < 200 || tempKelvin > 350) {
    console.log(`Invalid temperature value: ${tempKelvin}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert Kelvin to Fahrenheit
  const tempFahrenheit = (tempKelvin - 273.15) * 9/5 + 32;

  // 5. Validation & Final Answer
  console.log(`Max temperature in July 2022: ${tempFahrenheit.toFixed(1)}°F`);

  if (tempFahrenheit >= 95) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
